function validate([n, edges, restricted]) {
  if (!Number.isInteger(n) || n < 2 || n > 100000) return 'n must be between 2 and 10^5.';
  if (!Array.isArray(edges) || edges.length !== n - 1) return 'edges must hold exactly n - 1 pairs.';
  const parent = Array.from({ length: n }, (_, i) => i);
  const find = x => { while (parent[x] !== x) { parent[x] = parent[parent[x]]; x = parent[x]; } return x; };
  for (const edge of edges) {
    if (!Array.isArray(edge) || edge.length !== 2) return 'Each edge is a pair [a, b].';
    const [a, b] = edge;
    if (!Number.isInteger(a) || !Number.isInteger(b) || a < 0 || b < 0 || a >= n || b >= n) return 'Edge endpoints must be between 0 and n - 1.';
    if (a === b) return 'An edge must join two different nodes.';
    const ra = find(a), rb = find(b);
    if (ra === rb) return 'The edges must form a tree (no cycles).';
    parent[ra] = rb;
  }
  if (!Array.isArray(restricted) || restricted.length < 1 || restricted.length >= n) return 'restricted needs between 1 and n - 1 nodes.';
  const seen = new Set();
  for (const node of restricted) {
    if (!Number.isInteger(node) || node < 1 || node >= n) return 'Restricted nodes are between 1 and n - 1 (node 0 is never restricted).';
    if (seen.has(node)) return 'Restricted nodes must be distinct.';
    seen.add(node);
  }
  return null;
}

