function reachableNodes(n, edges, restricted) {
  // Grow the reached set by sweeping all edges until nothing new is added.
  const banned = new Set(restricted);
  const reached = new Set([0]);
  let changed = true;
  while (changed) {
    changed = false;
    for (const [a, b] of edges) {
      if (banned.has(a) || banned.has(b)) continue;
      if (reached.has(a) && !reached.has(b)) { reached.add(b); changed = true; }
      if (reached.has(b) && !reached.has(a)) { reached.add(a); changed = true; }
    }
  }
  return reached.size;
}

