function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? 2000 : int(2, 10);
  const deep = rand() < 0.5;
  // Build a random tree on positions, then give the positions shuffled labels.
  const label = Array.from({ length: n }, (_, i) => i);
  for (let i = n - 1; i > 0; i--) { const j = int(0, i); [label[i], label[j]] = [label[j], label[i]]; }
  const edges = [];
  for (let i = 1; i < n; i++) {
    const p = deep ? i - 1 - Math.floor(rand() * Math.min(i, 3)) : Math.floor(rand() * i);
    edges.push(rand() < 0.5 ? [label[i], label[p]] : [label[p], label[i]]);
  }
  for (let i = edges.length - 1; i > 0; i--) { const j = int(0, i); [edges[i], edges[j]] = [edges[j], edges[i]]; }
  const others = Array.from({ length: n - 1 }, (_, i) => i + 1);
  for (let i = others.length - 1; i > 0; i--) { const j = int(0, i); [others[i], others[j]] = [others[j], others[i]]; }
  const k = size === 'large' ? int(1, rand() < 0.5 ? 10 : 300) : int(1, n - 1);
  return [n, edges, others.slice(0, k)];
}
